create index work_operations_branch_status_idx on work_operations (branch_id, status, started_at desc);
create index work_operations_task_idx on work_operations (task_id) where task_id is not null;
create index work_operations_trip_idx on work_operations (trip_id) where trip_id is not null;
create index cargo_places_branch_status_idx on cargo_places (current_branch_id, status) where current_branch_id is not null;
create index cargo_places_trip_status_idx on cargo_places (current_trip_id, status) where current_trip_id is not null;
create index cargo_places_vehicle_idx on cargo_places (current_vehicle_id) where current_vehicle_id is not null;
create index cargo_item_places_place_idx on cargo_item_places (cargo_place_id);
create index cargo_place_measurements_place_time_idx on cargo_place_measurements (cargo_place_id, measured_at desc);
create index place_label_aliases_place_idx on place_label_aliases (cargo_place_id, status);
create index operation_places_place_idx on operation_places (cargo_place_id);
create index place_events_place_history_idx on place_events (cargo_place_id, occurred_at desc, received_at desc);
create index place_events_operation_idx on place_events (work_operation_id) where work_operation_id is not null;
create index place_events_task_idx on place_events (task_id) where task_id is not null;
create index place_events_trip_idx on place_events (trip_id) where trip_id is not null;
create index place_events_branch_time_idx on place_events (branch_id, occurred_at desc);
create index place_events_actor_branch_idx on place_events (actor_user_id, branch_id);
create index manifest_places_place_idx on manifest_places (cargo_place_id);
create index discrepancies_open_idx on discrepancies (branch_id, severity, created_at) where status in ('open', 'needs_review');
create index discrepancies_place_idx on discrepancies (cargo_place_id) where cargo_place_id is not null;
create index discrepancies_operation_idx on discrepancies (work_operation_id);
create index discrepancy_events_history_idx on discrepancy_events (discrepancy_id, occurred_at);
create index media_objects_branch_status_idx on media_objects (branch_id, status, created_at desc);
create index media_objects_checksum_idx on media_objects (storage_provider, bucket, checksum_sha256);
create index documents_order_idx on documents (order_id) where order_id is not null;
create index documents_trip_idx on documents (trip_id) where trip_id is not null;
create index documents_branch_status_idx on documents (branch_id, status);
create index document_versions_manifest_idx on document_versions (source_manifest_version_id) where source_manifest_version_id is not null;
create index signatures_media_idx on signatures (signature_media_id) where signature_media_id is not null;
create index document_signatures_signature_idx on document_signatures (signature_id);
create index order_media_media_idx on order_media (media_id);
create index cargo_place_media_media_idx on cargo_place_media (media_id);
create index work_operation_media_media_idx on work_operation_media (media_id);
create index document_version_media_media_idx on document_version_media (media_id);
create index integration_links_local_idx on integration_entity_links (entity_type, local_id);
create index integration_attempts_retry_idx on integration_attempts (next_retry_at) where status = 'retry';
create index outbox_ready_idx on outbox_messages (available_at, id) where status in ('pending', 'retry');
create index audit_log_entity_idx on audit_log (entity_type, entity_id, occurred_at desc) where entity_id is not null;
