create function guard_manifest_place_mutation()
returns trigger
language plpgsql
as $$
declare
  target_manifest_id uuid;
  target_status text;
begin
  if tg_op = 'DELETE' then
    target_manifest_id := old.manifest_version_id;
  else
    target_manifest_id := new.manifest_version_id;
  end if;
  select status into target_status from manifest_versions where id = target_manifest_id;
  if target_status <> 'draft' then
    raise exception 'Manifest % is % and immutable', target_manifest_id, target_status;
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create trigger manifest_places_draft_only
  before insert or update or delete on manifest_places
  for each row execute function guard_manifest_place_mutation();

create function guard_locked_manifest_version()
returns trigger
language plpgsql
as $$
begin
  if old.status in ('confirmed', 'superseded') then
    raise exception 'Confirmed/superseded manifest versions are immutable';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create trigger manifest_versions_lock
  before update or delete on manifest_versions
  for each row execute function guard_locked_manifest_version();

create function guard_issued_document_version()
returns trigger
language plpgsql
as $$
begin
  if old.status in ('issued', 'void') then
    raise exception 'Issued/void document versions are immutable; create a new version';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

create trigger document_versions_lock
  before update or delete on document_versions
  for each row execute function guard_issued_document_version();

create view cargo_place_current_v with (security_invoker = true) as
select
  p.id as place_id,
  p.human_label,
  p.order_id,
  o.order_number,
  p.place_number,
  p.place_count_at_creation as total_places,
  p.status,
  p.current_location_kind,
  p.current_location_label,
  p.current_branch_id,
  b.name as current_branch_name,
  p.current_vehicle_id,
  v.vehicle_number,
  p.current_trip_id,
  t.trip_number,
  m.length,
  m.width,
  m.height,
  m.dimension_state,
  m.dimension_unit,
  m.weight,
  m.weight_unit,
  m.weight_source,
  m.unknown_reason,
  p.version,
  p.updated_at
from cargo_places p
join orders o on o.id = p.order_id
left join cargo_place_measurements m on m.id = p.current_measurement_id
left join branches b on b.id = p.current_branch_id
left join vehicles v on v.id = p.current_vehicle_id
left join trips t on t.id = p.current_trip_id;

create view cargo_place_history_v with (security_invoker = true) as
select
  e.cargo_place_id as place_id,
  e.id as event_id,
  e.event_type,
  e.entity_version,
  e.occurred_at,
  e.received_at,
  e.actor_user_id,
  u.display_name as actor_name,
  e.branch_id,
  b.name as branch_name,
  e.task_id,
  e.trip_id,
  e.reason,
  e.payload
from place_events e
join app_users u on u.id = e.actor_user_id
join branches b on b.id = e.branch_id;

